import type { AttributeValue, UnitCode } from '@/types/models'
import type { CertificationCode } from '@/config/certifications'
import type { L10n, ProductTemplate } from './types'

type Tri = [en: string, de: string, ro: string]
const l10n = ([en, de, ro]: Tri): L10n => ({ en, de, ro })

interface Row {
  key: string
  category: string
  names: Tri
  summary: Tri
  keywords: string[]
  unit: UnitCode
  moq: number
  eur: number
  stock: [number, number]
  attributes: Record<string, AttributeValue>
  certs: CertificationCode[]
  producer: string
  shelf?: [number, number]
  mto?: [number, number]
}

const tpl = (r: Row): ProductTemplate => ({
  key: `x-${r.key}`,
  category: r.category,
  names: l10n(r.names),
  summary: l10n(r.summary),
  keywords: r.keywords,
  unit: r.unit,
  moq: r.moq,
  priceEUR: r.eur,
  shelfLifeDays: r.shelf,
  madeToOrderDays: r.mto,
  stock: r.stock,
  attributes: r.attributes,
  certifications: r.certs,
  producers: [r.producer],
})

const veg = (variety: string, cls: string, cal: number | undefined, temp: number, pack: string, organic = false): Record<string, AttributeValue> => ({
  variety,
  qualityClass: cls,
  organic,
  ...(cal ? { caliberMm: cal } : {}),
  storageTempC: temp,
  packaging: pack,
})

